//! The data of ICU's root collator as GNU R 4.6.2 opens it in the oracle
//! image (`ucol_open` after `uloc_setDefault("C.UTF-8")`, util.c:Scollate),
//! whose libicu is 76.1: ICU 76.1's root collation (CLDR 46, Unicode 16.0)
//! and Unicode 16.0's canonical decompositions, which the collator reads its
//! input through. ICU4X's datagen baked them (`data/`, generated by
//! `scripts/collate-data.sh`, which says where each comes from); [`Root`]
//! is the provider `icu_collator::Collator::try_new_unstable` takes.
//!
//! Root only: no locale's tailoring or reordering. The metadata and
//! diacritics markers list every locale's entry (datagen does not filter
//! them; about 1.3 KB), but a root collator reads only `und`'s.
//!
//! `unsafe`: only the generated code's, in [`baked`]'s data.

#![deny(unsafe_code)]

// The checkout this crate is built from (.cargo/config.toml): cargo then
// rebuilds the crate when another worktree built it last in a shared
// target directory.
const _: Option<&str> = option_env!("ROBIGO_WORKTREE");

pub use baked::Root;

// The generated macros (each data file defines one, `impl_<marker>!`, and
// holds no code until [`baked`] expands it).
include!("../data/collation_root_v1.rs.data");
include!("../data/collation_jamo_v1.rs.data");
include!("../data/collation_special_primaries_v1.rs.data");
include!("../data/collation_metadata_v1.rs.data");
include!("../data/collation_diacritics_v1.rs.data");
include!("../data/normalizer_nfd_data_v1.rs.data");
include!("../data/normalizer_nfd_tables_v1.rs.data");
include!("../data/normalizer_nfd_supplement_v1.rs.data");

// The generated code builds each payload over its bytes without checking
// them (`ZeroVec::from_bytes_unchecked`, `CodePointTrie::
// from_parts_unstable_unchecked_v1`, `DataRef::from_trie_and_refs_unchecked`):
// datagen wrote those bytes from structs it had validated, for the icu_*
// minor version Cargo.toml pins (2.3), which is what makes them sound.
#[allow(unsafe_code, clippy::undocumented_unsafe_blocks)]
mod baked {
    use icu_collator::provider::{CollationReorderingV1, CollationTailoringV1};
    use icu_provider::prelude::*;

    /// ICU 76.1's root collation and Unicode 16.0's NFD, baked.
    #[derive(Clone, Copy, Debug, Default)]
    pub struct Root;

    const _: () = {
        // datagen's mod.rs `make_provider!`
        impl Root {
            #[allow(dead_code)]
            pub(crate) const MUST_USE_MAKE_PROVIDER_MACRO: () = ();
        }
        icu_provider::marker::impl_data_provider_never_marker!(Root);
        super::impl_collation_root_v1!(Root);
        super::impl_collation_jamo_v1!(Root);
        super::impl_collation_special_primaries_v1!(Root);
        super::impl_collation_metadata_v1!(Root);
        super::impl_collation_diacritics_v1!(Root);
        super::impl_normalizer_nfd_data_v1!(Root);
        super::impl_normalizer_nfd_tables_v1!(Root);
        super::impl_normalizer_nfd_supplement_v1!(Root);
    };

    // The root collation has no tailoring and no reordering (its metadata
    // says so, and the collator then never asks for them).
    impl DataProvider<CollationTailoringV1> for Root {
        fn load(&self, req: DataRequest) -> Result<DataResponse<CollationTailoringV1>, DataError> {
            Err(DataErrorKind::MarkerNotFound.with_req(CollationTailoringV1::INFO, req))
        }
    }

    impl DataProvider<CollationReorderingV1> for Root {
        fn load(&self, req: DataRequest) -> Result<DataResponse<CollationReorderingV1>, DataError> {
            Err(DataErrorKind::MarkerNotFound.with_req(CollationReorderingV1::INFO, req))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::Root;
    use icu_normalizer::DecomposingNormalizer;
    use icu_normalizer::properties::{CanonicalCombiningClassMap, CanonicalDecomposition, Decomposed};

    /// The NFD data (from ICU 77.1's export) is Unicode 16.0's: each code
    /// point's canonical decomposition and combining class, where either is
    /// not trivial, hashed (FNV-1a 64 over `cp:nfd:ccc` lines in hex) as
    /// Python 3.14's unicodedata 16.0.0 gives them.
    #[test]
    fn nfd_is_unicode_16() {
        let nfd = DecomposingNormalizer::try_new_nfd_unstable(&Root).unwrap();
        let ccc = CanonicalCombiningClassMap::try_new_unstable(&Root).unwrap();
        let (nfd, ccc) = (nfd.as_borrowed(), ccc.as_borrowed());
        let (mut h, mut n) = (0xcbf2_9ce4_8422_2325_u64, 0);
        for c in (0..0x11_0000).filter_map(char::from_u32) {
            let mut buf = [0; 4];
            let d = nfd.normalize(c.encode_utf8(&mut buf));
            let k = ccc.get32_u8(c as u32);
            if d.len() == c.len_utf8() && d.starts_with(c) && k == 0 {
                continue;
            }
            n += 1;
            let ds: Vec<String> = d.chars().map(|x| format!("{:x}", x as u32)).collect();
            for b in format!("{:x}:{}:{k}\n", c as u32, ds.join(" ")).bytes() {
                h = (h ^ b as u64).wrapping_mul(0x0100_0000_01b3);
            }
        }
        assert_eq!((n, h), (14183, 0x5296_ce5a_9f1c_bb84));
    }

    /// The one-step decompositions (robigo-text's FCD check reads them)
    /// lead to NFD's first and last code points' classes.
    #[test]
    fn one_step_decompositions_reach_nfd() {
        let nfd = DecomposingNormalizer::try_new_nfd_unstable(&Root).unwrap();
        let one = CanonicalDecomposition::try_new_unstable(&Root).unwrap();
        let ccc = CanonicalCombiningClassMap::try_new_unstable(&Root).unwrap();
        let (nfd, one, ccc) = (nfd.as_borrowed(), one.as_borrowed(), ccc.as_borrowed());
        fn ends(one: &icu_normalizer::properties::CanonicalDecompositionBorrowed<'_>, c: char) -> (char, char) {
            match one.decompose(c) {
                Decomposed::Default => (c, c),
                Decomposed::Singleton(d) => ends(one, d),
                Decomposed::Expansion(a, b) => (ends(one, a).0, ends(one, b).1),
            }
        }
        for c in (0..0x11_0000).filter_map(char::from_u32) {
            let d = nfd.normalize(c.encode_utf8(&mut [0; 4])).into_owned();
            let want = (d.chars().next().unwrap(), d.chars().next_back().unwrap());
            let got = ends(&one, c);
            assert_eq!(
                (ccc.get32_u8(got.0 as u32), ccc.get32_u8(got.1 as u32)),
                (ccc.get32_u8(want.0 as u32), ccc.get32_u8(want.1 as u32)),
                "U+{:04X}",
                c as u32
            );
        }
    }
}
